using System;using System.Linq;
namespace GearLab {
 public static class TransmissionLoads {
  public static void Append(Result r){if(!r.Valid)return;var p=r.P;if(p.Efficiency<=0||p.Efficiency>1||p.InputTorque<0){r.Error("КПД должен быть (0;1], входной момент — неотрицательным.","Efficiency","InputTorque");return;}var e=r.Engineering;if(e==null){e=new TransmissionEngineering{Efficiency=p.Efficiency,SpeedGain=TrainSolver.Gain(r)};e.OutputRpm=p.InputRpm*e.SpeedGain;e.OutputTorque=p.InputTorque*r.Actual*p.Efficiency;e.InputPower=p.InputTorque*Math.Abs(p.InputRpm)*Math.PI/30;e.OutputPower=e.InputPower*p.Efficiency;r.Loads=e;r.Metric("КПД (задан)",Engine.F(p.Efficiency));r.Metric("Выходные обороты",Engine.F(e.OutputRpm)+" об/мин");r.Metric("Теоретический момент при КПД",Engine.F(e.OutputTorque)+" Н·м — не допустимый момент");if(p.Kind==1){e.Tangential=2000*p.InputTorque/(p.Module*r.Z1);e.Radial=e.Tangential*Math.Tan(20*Math.PI/180);r.Metric("Ft / Fr (приближённо)",Engine.F(e.Tangential)+" / "+Engine.F(e.Radial)+" Н");}}
   r.Loads=e;if(p.ServiceFactor<1||p.ServiceFactor>10||p.AllowableBendingMPa<0||p.AllowableBendingMPa>2000){r.Error("Коэффициент нагрузки 1–10; допустимое напряжение 0–2000 МПа.");return;}
   if((p.Kind==1||p.Kind==12)&&p.Teeth>=17&&Math.Abs(p.PressureAngle-20)<1e-8){double y=Math.PI*(.154-.912/p.Teeth),sigma=e.Tangential*p.ServiceFactor/(p.Thickness*p.Module*y);r.Metric("Lewis: изгиб зуба (оценка)",Engine.F(sigma)+" МПа");r.Metric("Запас по заданному напряжению",p.AllowableBendingMPa<=0?"Не определён: материал/допускаемое напряжение не заданы":sigma<=0?"Нет нагрузки":Engine.F(p.AllowableBendingMPa/sigma));r.Notes.Add("Lewis, стандартная внешняя прямозубая шестерня 20°, z≥17: Y=π(0,154−0,912/z); σ≈Ft·K/(b·m·Y). Без концентрации у галтели, усталости, контактных напряжений и расчёта по ISO/AGMA. Допускаемое напряжение задаёт пользователь; 0 означает неизвестно.");}else r.Metric("Изгиб / контакт / запас","Не определены: для этой геометрии обоснованная методика не реализована");
  }
 }
}
